            cenarios={res.cenarios}
            recomendadoId={res.recomendacao?.cenario_id}
          />

          {/* Cards por cenário */}
          <div className= | >
              {cenario.base_legal}
            </span>
          )}
        </div>
      </div>

      {inaplicavel ? (
        <div className= | >
              {res.base_legal_geral}
            </p>
          )}

          {/* Peça de conversão */}
