          {recomendado && res.recomendacao?.racional && (
            <div className= | >
          {res?.aviso_hitl || AVISO_HITL_FALLBACK}
        </p>
      </div>

      {/* Formulário */}
      <div className= | >
        Barra em dourado = menor desembolso estimado entre os caminhos
        aplicáveis. Valores preliminares.
      </p>
    </div>
  );
}

