    const response = await api.get<AuditEntry[]>(
      `/atendimentos/${itemId}/historico`,
    );
    setAuditById((current) => ({
      ...current,
      [itemId]: response.data ?? [],
    }));
  } catch (error: any) {
    toast.error(
      error.response?.data?.detail ||
         | ,
    );
  } finally {
    setUpdatingId(null);
  }
}

