                <span className= | >v{dossie.versao}</Badge>
              {dossie.status ===  | >{avisoFaltantes}</p>
            )}
            {Array.isArray(faltantes) &&
              faltantes.length === 0 &&
              !avisoFaltantes && (
                <p className= | >{e.descricao}</span>
                      </li>
                    ))}
                  </ul>
                  {eventos.length > EVENTOS_VISIVEIS && !todosEventos && (
                    <button
                      className= | >{f.detalhe}</span>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* ── Linha do tempo ────────────────────────────────────────────── */}
          {lt && (
            <div className= | >{p.detalhe}</span>
                        )}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Eventos */}
              {eventos.length === 0 ? (
                <p className= | >{tese.area_juridica}</span>
        )}
        {tese.taxa_sucesso != null && (
          <span className= | >{tese.descricao}</p>
      )}
      {tese.fundamentacao && (
        <p className= | >—</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* ── Provas faltantes (sugestão de IA, sob demanda) ────────────── */}
          <div className= | }
                        </Badge>
                        <span className= | }
                    .
                  </span>
                </div>
              )}

              {/* Próximos passos */}
              {lt.proximos_passos.length > 0 && (
                <div>
                  <h4 className= | }
                  <strong>revisão humana obrigatória</strong> antes de uso.
                </span>
              </div>
