interface TeseSugerida {
  id: string;
  titulo: string;
  tema: string | null;
  ramo: string | null;
  resumo: string;
  score: number;
  distancia: number;
  taxa_sucesso: number | null;
  vezes_venceu: number | null;
  vezes_usada: number | null;
  tribunal: string | null;
}

interface TesesSugeridasResp {
  case_id: string;
  estrategia: string | null;
  area: string | null;
  palavras_chave: string[];
  total: number;
  teses: TeseSugerida[];
}

