  // Preview da materialização da extração de IA (dry_run) antes de aplicar.
  const [preview, setPreview] = useState<{
    caseId: string;
    caseTitulo: string;
    extracao: ExtracaoPayload;
    result: AplicarExtracaoResult;
  } | null>(null);
  const [aplicando, setAplicando] = useState(false);
