                type= | >
                Nenhum lançamento de horas.
              </p>
            ) : (
              <div className= | >
                Nenhum movimento registrado.
              </p>
            ) : (
              <div className= | >
                Nenhum prazo nos próximos 30 dias.
              </p>
            ) : (
              <div className= | >
                Nenhuma tese vinculada.
              </p>
            ) : (
              <div className= | >
                Prob. de êxito (%)
              </label>
              <input
                type= | >
                Sem advogados vinculados.
              </p>
            ) : (
              <div className= | >
                Tempo estimado (anos)
              </label>
              <input
                type= | >
