export default function RamoBase() {
  const { slug } = useParams<{ slug: string }>();
  const cfg: RamoConfig | undefined = slug ? RAMOS[slug] : undefined;

  const [lista, setLista] = useState<any[] | null>(null);
  const [casos, setCasos] = useState<Case[]>([]);
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState<any>({});
  const [salvando, setSalvando] = useState(false);

  const Icone = useMemo(() => {
    if (!cfg) return Folder;
    return ICONES[cfg.icone] || Folder;
  }, [cfg]);

  const load = () => {
    if (!cfg) return;
    if (cfg.externo) {
      setLista([]);
      return;
    }
    api
      .get(cfg.endpoint)
      .then((r) => setLista(r.data.data || []))
      .catch(() => setLista([]));
  };

  useEffect(() => {
    if (!cfg) return;
    setLista(null);
    setForm({});
    load();
    api
      .get( | >
              ✍️ Gerar minuta
            </button>
          </div>
          {acao && <p className= | >
              ➡ {res.proxima_acao}
            </p>
          )}
          <div className= | >
              💾 Salvar no caso
            </button>
            <button onClick={gerarMinuta} className= | >
            Ferramentas públicas
          </h2>
          <div className= | >
            Mercado em {res.periodo} · {res.instituicoes} instituições · fonte:
            BACEN
