  rag.forEach((r) => {
    const k = `${normTitulo(r.titulo)}|${r.categoria ??  | ,
      score: hit.score,
      chunksAgrupados: chunks > 1 ? chunks : undefined,
      rag: hit,
    });
  });

  return out.sort((a, b) => b.relevancia - a.relevancia);
}

