    return `${partes.join( | ../components/Dashboards | ../components/Toast | ../components/UI | ../lib/api | ../lib/list | ../stores/auth | /biblioteca | /conhecimento | /memoria | : rotas existentes no app. Não há rota dedicada de
  // jurisprudência interna (só o link_original externo, quando cadastrado).
  const origem =
